"""Build the documentary page and editorial script from data/documentary.json. No dependencies."""
from pathlib import Path
import json,html
R=Path(__file__).resolve().parents[1]
D=json.loads((R/'data/documentary.json').read_text())
C={c['id']:c for c in D['chapters']}
e=html.escape

def intro(id):
 c=C[id]
 return f'<div class="chapter-heading"><p class="eyebrow"><span>{c["number"]} /</span> {e(c["date"])}</p><h2>{e(c["title"])}</h2><p class="deck">{e(c["deck"])}</p></div>'
def prose(id):return '<div class="prose">'+''.join('<p>'+e(p)+'</p>' for p in C[id]['paragraphs'])+'</div>'
def source(id,label):return f'<button class="source-link" data-source="{id}">{e(label)} <span aria-hidden="true">↗</span></button>'

def scene(key, title, caption):
 return f'<figure class="reconstruction" data-scene="{key}"><div class="scene-topline"><span>İSTANBUL · YENİDEN CANLANDIRMA</span><span>{title}</span></div><div class="scene-stage"><canvas data-scene-canvas="{key}" aria-label="{caption}"></canvas><svg class="city-drawing" viewBox="0 0 1440 270" preserveAspectRatio="none" aria-hidden="true"><path class="far-shore" d="M0 151Q160 139 245 151T470 145T720 156T970 145T1220 151T1440 145V270H0Z"/><path class="waterline" d="M385 187H1010m-580 10h290m70 9h250m-600 4h170m175 13h180"/><g class="boats"><path d="M545 178h45l-9 7h-28Zm21 0v-45l17 36h-17m254 15h54l-12 8h-29Zm24 0v-59m-1 7-18 43h18m4-40 13 40h-13"/></g><g class="roof-mass"><path d="M0 270V132l73-28 102 34v18h24v-44l88-27 98 43v142Zm1044 0v-86l58-23 95 30v-71l92-33 120 40v143Z"/><path d="M39 123v-45h18v-10h32v10h16v35m144-16V49h17V37h24v12h18v45m940 13V63h17V52h25v11h17v37"/></g><g class="roof-light"><path d="m0 132 73-28 102 34m24-26 88-27 98 43m812-8 92-33 120 40M73 107v62m214-80v92m1002-91v82M2 183l172 20m25-39 183 22m817-18 210 26M39 78h66m144-29h59m940 14h59"/><path d="M25 224v24h17v-22m72 2v22h18v-19m98-27v30h18v-28m62 15v30h20v-27m899-17v30h19v-27m51 17v27h20v-25"/></g><path class="foreground-edge" d="M0 256q110-11 203 1t194-2 187 2 239-1 211 0 206 1 200-3v16H0Z"/></svg></div><figcaption><div><span>{caption}</span><button class="scene-label-toggle" data-scene-labels="{key}" aria-pressed="true">Gökteki adları gizle</button></div><details><summary>Sahne nasıl kuruldu?</summary><p>Gökyüzü: belirtilen an için Galata (41,02562° K, 28,97414° D); yıldızlar ve Halley’in başı hesaplanır. Çatı çizgisi: dönem Galata fotoğraflarından esinlenen özgün, stilize çizim; bina ölçümü veya gerçek görüş engeli modeli değildir. Kuyruğun uzunluğu ve parlaklığı temsilîdir. Hava açık kabul edilmiştir.</p></details></figcaption></figure>'

